package com.finbank.support;
import com.finbank.support.dto.*;import com.finbank.support.entity.*;import com.finbank.support.repository.SupportTicketRepository;import com.finbank.support.service.SupportServiceImpl;import org.junit.jupiter.api.Test;import org.mockito.Mockito;import static org.junit.jupiter.api.Assertions.*;
class SupportServiceImplTest{@Test void shouldCreateTicket(){SupportTicketRepository repo=Mockito.mock(SupportTicketRepository.class);SupportServiceImpl service=new SupportServiceImpl(repo);SupportTicket saved=new SupportTicket();saved.setTicketReference("TKT123");saved.setCustomerNumber("FB123");saved.setRequestType(RequestType.COMPLAINT);saved.setPriority(Priority.HIGH);saved.setStatus(SupportStatus.OPEN);saved.setSubject("Card issue");saved.setDescription("Card payment failed");Mockito.when(repo.save(Mockito.any())).thenReturn(saved);TicketResponse r=service.create(new CreateTicketRequest("FB123",RequestType.COMPLAINT,Priority.HIGH,"Card issue","Card payment failed"));assertEquals("TKT123",r.ticketReference());assertEquals(SupportStatus.OPEN,r.status());}}